# Modern To-Do List Application

I'll create a sleek, functional to-do list application with a clean interface and smooth interactions.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Modern To-Do List</title>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }

        body {
            background: linear-gradient(135deg, #6e8efb, #a777e3);
            min-height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
            padding: 20px;
        }

        .container {
            width: 100%;
            max-width: 500px;
            background-color: white;
            border-radius: 16px;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
            overflow: hidden;
        }

        .header {
            background: linear-gradient(to right, #6e8efb, #a777e3);
            color: white;
            padding: 25px;
            text-align: center;
        }

        .header h1 {
            font-weight: 600;
            font-size: 28px;
            margin-bottom: 5px;
        }

        .header p {
            opacity: 0.9;
        }

        .input-area {
            display: flex;
            padding: 20px;
            border-bottom: 1px solid #eee;
        }

        .input-area input {
            flex: 1;
            padding: 14px;
            border: 2px solid #ddd;
            border-radius: 8px 0 0 8px;
            font-size: 16px;
            outline: none;
            transition: border-color 0.3s;
        }

        .input-area input:focus {
            border-color: #a777e3;
        }

        .input-area button {
            background-color: #6e8efb;
            color: white;
            border: none;
            padding: 14px 20px;
            border-radius: 0 8px 8px 0;
            cursor: pointer;
            font-weight: 600;
            transition: background-color 0.3s;
        }

        .input-area button:hover {
            background-color: #5a7dfa;
        }

        .filters {
            display: flex;
            justify-content: center;
            padding: 15px;
            background-color: #f9f9f9;
            border-bottom: 1px solid #eee;
        }

        .filters button {
            background: none;
            border: none;
            padding: 8px 15px;
            margin: 0 5px;
            border-radius: 20px;
            cursor: pointer;
            font-size: 14px;
            transition: all 0.3s;
        }

        .filters button.active {
            background-color: #6e8efb;
            color: white;
        }

        .filters button:hover:not(.active) {
            background-color: #eee;
        }

        .tasks {
            padding: 20px;
            max-height: 400px;
            overflow-y: auto;
        }

        .task {
            display: flex;
            align-items: center;
            padding: 15px;
            margin-bottom: 12px;
            background-color: #f9f9f9;
            border-radius: 8px;
            transition: transform 0.3s, box-shadow 0.3s;
        }

        .task:hover {
            transform: translateY(-2px);
            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
        }

        .task.completed {
            background-color: #f0f0f0;
        }

        .task.completed .task-text {
            text-decoration: line-through;
            color: #888;
        }

        .task-check {
            margin-right: 15px;
            width: 22px;
            height: 22px;
            cursor: pointer;
            border-radius: 50%;
            border: 2px solid #ddd;
            display: flex;
            justify-content: center;
            align-items: center;
            transition: background-color 0.3s, border-color 0.3s;
        }

        .task-check.checked {
            background-color: #6e8efb;
            border-color: #6e8efb;
            color: white;
        }

        .task-text {
            flex: 1;
            font-size: 16px;
            word-break: break-word;
        }

        .task-delete {
            color: #ff6b6b;
            cursor: pointer;
            padding: 8px;
            border-radius: 5px;
            transition: background-color 0.3s;
        }

        .task-delete:hover {
            background-color: rgba(255, 107, 107, 0.1);
        }

        .empty-state {
            text-align: center;
            padding: 30px;
            color: #888;
        }

        .empty-state i {
            font-size: 50px;
            margin-bottom: 15px;
            color: #ddd;
        }

        .stats {
            display: flex;
            justify-content: space-between;
            padding: 15px 20px;
            background-color: #f9f9f9;
            border-top: 1px solid #eee;
            color: #666;
            font-size: 14px;
        }

        @media (max-width: 600px) {
            .container {
                border-radius: 12px;
            }

            .header {
                padding: 20px 15px;
            }

            .input-area {
                padding: 15px;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1><i class="fas fa-tasks"></i> Task Manager</h1>
            <p>Organize your day with ease</p>
        </div>

        <div class="input-area">
            <input type="text" id="taskInput" placeholder="Enter a new task...">
            <button id="addTaskBtn"><i class="fas fa-plus"></i> Add</button>
        </div>

        <div class="filters">
            <button class="filter-btn active" data-filter="all">All</button>
            <button class="filter-btn" data-filter="active">Active</button>
            <button class="filter-btn" data-filter="completed">Completed</button>
        </div>

        <div class="tasks" id="tasksContainer">
            <!-- Tasks will be added here dynamically -->
            <div class="empty-state">
                <i class="fas fa-check-circle"></i>
                <h3>No tasks yet</h3>
                <p>Add a task to get started</p>
            </div>
        </div>

        <div class="stats">
            <span id="tasksCount">0 tasks</span>
            <span id="completedCount">0 completed</span>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const taskInput = document.getElementById('taskInput');
            const addTaskBtn = document.getElementById('addTaskBtn');
            const tasksContainer = document.getElementById('tasksContainer');
            const filterBtns = document.querySelectorAll('.filter-btn');
            const tasksCount = document.getElementById('tasksCount');
            const completedCount = document.getElementById('completedCount');

            let tasks = JSON.parse(localStorage.getItem('tasks')) || [];
            let currentFilter = 'all';

            // Initialize the app
            renderTasks();
            updateStats();

            // Add task event
            addTaskBtn.addEventListener('click', addTask);
            taskInput.addEventListener('keypress', function(e) {
                if (e.key === 'Enter') addTask();
            });

            // Filter events
            filterBtns.forEach(btn => {
                btn.addEventListener('click', function() {
                    filterBtns.forEach(b => b.classList.remove('active'));
                    this.classList.add('active');
                    currentFilter = this.getAttribute('data-filter');
                    renderTasks();
                });
            });

            function addTask() {
                const taskText = taskInput.value.trim();
                if (taskText === '') return;

                const newTask = {
                    id: Date.now(),
                    text: taskText,
                    completed: false,
                    timestamp: new Date().toISOString()
                };

                tasks.unshift(newTask);
                saveTasks();
                renderTasks();
                updateStats();

                taskInput.value = '';
                taskInput.focus();
            }

            function renderTasks() {
                let filteredTasks = tasks;

                if (currentFilter === 'active') {
                    filteredTasks = tasks.filter(task => !task.completed);
                } else if (currentFilter === 'completed') {
                    filteredTasks = tasks.filter(task => task.completed);
                }

                if (filteredTasks.length === 0) {
                    tasksContainer.innerHTML = `
                        <div class="empty-state">
                            <i class="fas fa-check-circle"></i>
                            <h3>No tasks ${currentFilter !== 'all' ? currentFilter : ''}</h3>
                            <p>${currentFilter === 'all' ? 'Add a task to get started' : 'No tasks match this filter'}</p>
                        </div>
                    `;
                    return;
                }

                tasksContainer.innerHTML = '';

                filteredTasks.forEach(task => {
                    const taskElement = document.createElement('div');
                    taskElement.className = `task ${task.completed ? 'completed' : ''}`;
                    taskElement.setAttribute('data-id', task.id);

                    taskElement.innerHTML = `
                        <div class="task-check ${task.completed ? 'checked' : ''}">
                            ${task.completed ? '<i class="fas fa-check"></i>' : ''}
                        </div>
                        <div class="task-text">${task.text}</div>
                        <div class="task-delete"><i class="fas fa-trash-alt"></i></div>
                    `;

                    tasksContainer.appendChild(taskElement);

                    // Add event for task completion toggle
                    const checkBtn = taskElement.querySelector('.task-check');
                    checkBtn.addEventListener('click', () => toggleTask(task.id));

                    // Add event for task deletion
                    const deleteBtn = taskElement.querySelector('.task-delete');
                    deleteBtn.addEventListener('click', () => deleteTask(task.id));
                });
            }

            function toggleTask(id) {
                tasks = tasks.map(task => {
                    if (task.id === id) {
                        return {...task, completed: !task.completed};
                    }
                    return task;
                });

                saveTasks();
                renderTasks();
                updateStats();
            }

            function deleteTask(id) {
                tasks = tasks.filter(task => task.id !== id);
                saveTasks();
                renderTasks();
                updateStats();
            }

            function updateStats() {
                const totalTasks = tasks.length;
                const completedTasks = tasks.filter(task => task.completed).length;

                tasksCount.textContent = `${totalTasks} task${totalTasks !== 1 ? 's' : ''}`;
                completedCount.textContent = `${completedTasks} completed`;
            }

            function saveTasks() {
                localStorage.setItem('tasks', JSON.stringify(tasks));
            }
        });
    </script>
</body>
</html>
```

## Features

This to-do list application includes:

1. **Clean, modern UI** with gradient background and card layout
2. **Task management** - add, complete, and delete tasks
3. **Filtering system** - view all, active, or completed tasks
4. **Statistics** - shows total tasks and completed count
5. **Local storage** - tasks persist between browser sessions
6. **Responsive design** - works well on both desktop and mobile devices
7. **Smooth animations** - for a more polished user experience
8. **Empty states** - helpful messages when no tasks are present

To use the application, simply type a task in the input field and press Enter or click the Add button. You can mark tasks as complete by clicking the circle icon or delete them using the trash icon.
